import{dueAnnouncements}from'./announcements-due.mjs';
import{meetingListStatus as meetingStatus,meetingStatusLabel}from'./meeting-status.mjs';
import{programOf,LEGACY_PROGRAM}from'./programs.mjs';
import{createWorkspace}from'./workspace.mjs';
import{dubaiDate,prettyDate,message,phoneDigits,phoneList,validPhoneList,waUrl,tasksFor,statusOf,timeLabel,timeRange,normalizeMeetingEdit,applyMeetingEdits}from'./core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dueOnly=document.documentElement.classList.contains("due-only");
let extension;
const bundledPosters=new Map();
let bundledMeetings=[],baseMeetings=[],meetings=[],tasks=[],activeProgram=localStorage.getItem('gubae-active-program')||LEGACY_PROGRAM,view='queue',meetingFilter='all',filter='due',kind='all',query='',today=dubaiDate(),selected=null,activePoster=null,posterUrl=null,toastTimer;
const KEY='gubae-announcements-v1';let state={recipients:{},sent:{},meetingEdits:{}};
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object')state={recipients:raw.recipients||{},sent:raw.sent||{},meetingEdits:raw.meetingEdits||{}}}catch{toast('Saved settings could not be read. Restore a backup in Setup.');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000)}
function save(){if(extension?.persist(state))return true;try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Could not save on this device. Export a backup before closing.');return false}}
const dbp=new Promise((resolve,reject)=>{const r=indexedDB.open('gubae-posters',1);r.onupgradeneeded=()=>r.result.createObjectStore('posters');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});dbp.catch(()=>{});
async function posterDB(action,id,value){const db=await dbp;return new Promise((resolve,reject)=>{const tx=db.transaction('posters',action==='get'||action==='getAllKeys'?'readonly':'readwrite');const store=tx.objectStore('posters');const r=action==='put'?store.put(value,id):action==='getAllKeys'?store.getAllKeys():store.get(id);r.onsuccess=()=>{if(action!=='put')resolve(r.result)};tx.oncomplete=()=>{if(action==='put')resolve(true)};tx.onerror=()=>reject(tx.error);r.onerror=()=>reject(r.error)})}
const recipient=m=>typeof state.recipients[m.id]==='string'?state.recipients[m.id]:'';
const sent=t=>!!state.sent[t.key];
const status=t=>statusOf(t,state.sent,today);
const label=s=>({today:'Due today',overdue:'Overdue',upcoming:'Upcoming',sent:'Marked sent',past:'Meeting passed'}[s]);
const badge=t=>`<span class="pill ${status(t)}">${label(status(t))}</span>`;
function stats(){const due=tasks.filter(t=>['today','overdue'].includes(status(t))).length;const sentCount=tasks.filter(sent).length;const recipients=meetings.filter(m=>validPhoneList(recipient(m))).length;$('#stats').innerHTML=[['READY FOR YOUR ATTENTION',due,'Due today + overdue','↗'],['UPCOMING MEETINGS',meetings.filter(m=>m.date>=today).length,'of '+meetings.length+' scheduled gatherings','▦'],['ANNOUNCEMENTS SENT',sentCount,'of '+tasks.length+' · confirmed by you','✓'],['RECIPIENTS SET UP',recipients,'of '+meetings.length+' private chats','♙']].map(([a,b,c,i])=>`<article class="stat"><span class="label">${a}</span><span class="stat-icon">${i}</span><strong>${b}</strong><span class="meta">${c}</span></article>`).join('');$('#navCount').textContent=due||'';$('#today').textContent=prettyDate(today);}
const searchBox=()=>`<input class="search" type="search" id="search" placeholder="Search mahbers…" aria-label="Search mahbers" value="${esc(query)}">`;
function row(t){const m=t.meeting;return`<article class="task-row"><div class="task-title"><span class="task-symbol ${t.type}">${t.type==='poster'?'▧':'↗'}</span><div><h3 lang="am">${esc(m.topic)}</h3><small>${t.type==='poster'?'Poster announcement · 3 days before':'Zoom invitation · 1 day before'} &nbsp; · &nbsp; #${m.id.padStart(2,'0')}</small></div></div><div class="date-cell">${prettyDate(t.due)}<small>Meeting ${prettyDate(m.date)}</small></div><div class="status-cell">${badge(t)}</div><div class="recipient-cell ${validPhoneList(recipient(m))?'':'missing'}">${validPhoneList(recipient(m))?'● Recipient ready':recipient(m)?'○ Check number':'○ Add recipient'}</div><button class="prepare" data-task="${t.key}">${sent(t)?'View':'Prepare'} <span>↗</span></button></article>`}
function match(m){return(m.topic+' '+m.date+' '+m.id).toLowerCase().includes(query.toLowerCase())}
function queue(){const count=f=>tasks.filter(t=>f==='all'||(f==='due'?['today','overdue'].includes(status(t)):status(t)===f)).length;const visible=tasks.filter(t=>match(t.meeting)&&(kind==='all'||t.type===kind)&&(filter==='all'||(filter==='due'?['today','overdue'].includes(status(t)):status(t)===filter)));return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Your announcement queue</h2><p class="section-subtitle">A clear plan for every mahber. All dates in Dubai time.</p></div>${searchBox()}</div><div class="filters">${[['due','Needs attention'],['upcoming','Upcoming'],['sent','Sent'],['all','All']].map(([f,l])=>`<button class="chip ${filter===f?'selected':''}" data-filter="${f}" aria-pressed="${filter===f}">${l}<em>${count(f)}</em></button>`).join('')}<select id="kind" aria-label="Announcement type"><option value="all">All announcements</option><option value="poster" ${kind==='poster'?'selected':''}>Posters only</option><option value="link" ${kind==='link'?'selected':''}>Zoom links only</option></select></div><div class="task-head"><span>MAHBER / ANNOUNCEMENT</span><span>SEND DATE</span><span>STATUS</span><span class="recipient-cell">RECIPIENT</span><span>ACTION</span></div>${visible.length?visible.map(row).join(''):`<div class="empty"><strong>${query?'No matching mahbers.':filter==='due'?'You’re all caught up.':'Nothing here yet.'}</strong><span>${filter==='due'?'Your next announcements will appear here when they are due.':'Try another filter or search.'}</span></div>`}<div class="bottom-note"><span>${visible.length} announcements shown · ${tasks.length} total</span><span>Opening WhatsApp does not mark an announcement sent.</span></div></div><div class="mode-notice"><span>◷</span><span><strong>You stay in control.</strong> Open a prepared announcement, send it in WhatsApp, then mark it sent here.</span><button id="modeHelp">About sending ↗</button></div>`}
function allMeetings(){const now=new Date(),reports=new Map((extension?.reports()||[]).map(r=>[r.meetingId||r.id,r]));const statuses=new Map(meetings.map(m=>[m.id,meetingStatus(m,reports.get(m.id),now)]));const visible=meetings.filter(m=>match(m)&&(meetingFilter==='all'||statuses.get(m.id)===meetingFilter)).sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id),undefined,{numeric:true}));return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">${meetings.length} gatherings, all prepared.</h2><p class="section-subtitle">Your gathering schedule · All times in Dubai</p></div>${searchBox()}</div><div class="filters meeting-filters" role="group" aria-label="Filter meetings by status">${[['all','All'],['missed','Missed'],['held','Held'],['upcoming','Upcoming'],['today','Today'],['overdue','Overdue'],['cancelled','Cancelled'],['postponed','Postponed']].map(([value,label])=>`<button class="chip ${meetingFilter===value?'selected':''}" data-meeting-filter="${value}" aria-pressed="${meetingFilter===value}">${label}<em>${value==='all'?meetings.length:meetings.filter(m=>statuses.get(m.id)===value).length}</em></button>`).join('')}</div><p class="meeting-filter-note">Submitting an organizer report marks Held. You can also set the status below. Today starts at 6:00 AM Dubai time on the gubae day and stays until its scheduled end. Before then, the meeting is Upcoming. Overdue means the scheduled end has passed without a report. All includes other reported outcomes.</p><div class="meeting-grid">${visible.map(m=>`<article class="meeting-card"><div class="poster-preview">${m.preview?`<img src="${m.preview}" alt="Canva preview for ${esc(m.topic)}" loading="lazy">`:'✣'}</div><div class="card-body"><span class="pill meeting-status ${statuses.get(m.id)}">${meetingStatusLabel(statuses.get(m.id))}</span><h3 lang="am">${esc(m.topic)}</h3><p>#${m.id.padStart(2,'0')} · ${prettyDate(m.date)} · ${timeLabel(m.startTime)}</p>${!m.link?'<p class="draft-note">Zoom link needed · draft invitation</p>':''}<button class="edit-meeting" data-edit="${m.id}">Edit gubae ✎${state.meetingEdits[m.id]?' · Edited':''}</button><button class="secondary" data-outcome="${m.id}">Set meeting status</button><div class="card-actions"><button class="prepare" data-task="${m.id}:poster">Poster ${state.sent[m.id+':poster']?'✓':'↗'}</button><button class="prepare" data-task="${m.id}:link">Zoom link ${state.sent[m.id+':link']?'✓':'↗'}</button></div></div></article>`).join('')||'<div class="empty">No meetings match this filter and search.</div>'}</div><div class="bottom-note">${visible.length} meetings shown · ${meetings.length} in this program</div></div>`}
function recipients(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">A familiar chat for every mahber.</h2><p class="section-subtitle">Import your matched contacts once, or edit numbers below.</p><label class="secondary" style="display:inline-block;margin-top:12px;cursor:pointer">Import contacts<input type="file" id="importBackup" accept="application/json,.json" hidden></label></div>${searchBox()}</div><div class="notice" style="margin:20px 24px">Use the country code, for example +971 50 123 4567. Separate alternate numbers with / . Numbers are stored only in this browser. For posters, choose this contact in WhatsApp’s share menu.</div>${meetings.filter(match).map(m=>`<div class="recipient-row"><div><h3 lang="am">${esc(m.topic)}</h3><small>#${m.id.padStart(2,'0')} · ${prettyDate(m.date)}</small></div><label class="field">WhatsApp number<input type="tel" autocomplete="off" data-phone="${m.id}" value="${esc(recipient(m))}" placeholder="+971 50 123 4567"><span class="field-hint" data-hint="${m.id}">${validPhoneList(recipient(m))?'Saved · '+phoneList(recipient(m)).length+' number(s)':recipient(m)?'Check number length · UAE numbers need 9 digits after +971':'Include country code'}</span></label></div>`).join('')}</div>`}
function setup(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Make it part of your routine.</h2><p class="section-subtitle">A simple frontend workspace, with your setup saved on your device.</p></div></div><div class="setup"><h3>Your announcement rhythm</h3><p>Poster: <strong>3 calendar days before</strong> each meeting.<br>Zoom invitation: <strong>1 calendar day before</strong> each meeting.<br>Default time: <strong>9:00–10:30 PM, Asia/Dubai.</strong> Edit individual gubaes under All meetings.</p><div class="notice">Open this app to see what is due. This version does not run in the background or send automatically. WhatsApp requires the final Send action.</div><h3>Original Canva posters</h3><p>All 41 original Canva PNG posters are included at 1080 × 1350 pixels. Open a poster announcement to share it directly. If you revise a design later, you can attach a replacement image on this device.</p><p id="posterCount">Checking attached posters…</p><h3>Keep a backup</h3><p>Your gubae edits, recipients, sent confirmations, and attached posters stay in this browser. Export a backup before changing devices or clearing browser data. Your backup includes attached images.</p><div class="button-row"><button class="primary" id="exportBackup">Export backup</button><label class="secondary" style="cursor:pointer">Restore backup<input type="file" id="importBackup" accept="application/json,.json" hidden></label><button class="secondary" id="downloadSchedule">Download send schedule</button></div><p class="muted">Restore merges saved gubae edits, recipients, sent confirmations, and posters with your current setup. This site does not synchronize between devices.</p><h3>Sending from your phone</h3><p>For poster sharing, use a browser that supports sharing image files to WhatsApp. Choose WhatsApp, select the intended private chat, and press Send. On unsupported browsers you can download the attached original and add it in WhatsApp.</p></div></div>`}
function renderDue(){const items=extension?.cloud()?dueAnnouncements(meetings,extension.reports(),new Date(),state.sent):null;$('#content').innerHTML=items===null?'<div class="empty">Connecting to announcements… <button class="secondary" id="retryDue">Retry</button></div>':items.length?items.map(t=>`<article class="due-card"><h2 lang="am">${esc(t.meeting.topic)}</h2><p>${t.type==='poster'?'Poster':'Zoom invitation'} · Meeting ${prettyDate(t.meeting.date)}</p><button class="primary" data-task="${esc(t.key)}">Prepare ${t.type==='poster'?'poster':'Zoom link'} ↗</button></article>`).join(''):'<div class="empty">No announcements due.</div>';bindContent();$('#retryDue')?.addEventListener('click',()=>location.reload());}
function render(preserveFocus=false){if(dueOnly){renderDue();return}stats();const titles={teachers:['Teachers, ready to connect.','Private contacts and prepared Zoom invitations.'],reports:['Listen to every gathering.','Reports from organizers, collected in one place.'],monthly:['See the month together.','Attendance, teaching feedback, and follow-up.'],queue:['Keep every gathering connected.','The right announcement, ready for the right day.'],meetings:['Every mahber. Every gathering.','Your posters and invitations, together in one place.'],recipients:['Set it up once. Stay connected.','The right private chat for each mahber.'],settings:['A simple system for your service.','Your schedule, saved details, and sending routine.']};$('#pageTitle').textContent=titles[view][0];$('#pageSubtitle').textContent=titles[view][1];$('#content').innerHTML=extension?.render(view)??(view==='queue'?queue():view==='meetings'?allMeetings():view==='recipients'?recipients():setup());document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});bindContent();extension?.afterRender();if(preserveFocus){const el=$('#search');el?.focus();el?.setSelectionRange(query.length,query.length)}if(view==='settings')posterDB('getAllKeys').then(keys=>{if($('#posterCount'))$('#posterCount').textContent='41 originals included · '+keys.length+' custom replacements saved on this device.'}).catch(()=>{if($('#posterCount'))$('#posterCount').textContent='Poster storage is unavailable in this browser.'})}
function bindContent(){document.querySelectorAll('[data-meeting-filter]').forEach(b=>b.onclick=()=>{meetingFilter=b.dataset.meetingFilter;render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#kind')?.addEventListener('change',e=>{kind=e.target.value;render()});$('#search')?.addEventListener('input',e=>{query=e.target.value;render(true)});document.querySelectorAll('[data-phone]').forEach(b=>b.addEventListener('input',e=>{const id=e.target.dataset.phone;state.recipients[id]=e.target.value;const valid=validPhoneList(e.target.value),ok=save();e.target.classList.toggle('invalid',!!e.target.value&&!valid);const hint=document.querySelector(`[data-hint="${id}"]`);hint.textContent=!ok?'Could not save':valid?'Saved · international number':e.target.value?'Check country code and number length':'Include country code';stats()}));$('#modeHelp')?.addEventListener('click',()=>$('#help').showModal());$('#exportBackup')?.addEventListener('click',exportBackup);$('#importBackup')?.addEventListener('change',importBackup);$('#downloadSchedule')?.addEventListener('click',downloadSchedule)}
async function openTask(key){const pending=tasks.find(t=>t.key===key);if(pending?.type==='link'&&!pending.meeting.link){openEditor(pending.meeting.id);toast('Add this gubae’s Zoom link before preparing its invitation.');return;}selected=tasks.find(t=>t.key===key);if(!selected)return;activePoster=null;if(posterUrl){URL.revokeObjectURL(posterUrl);posterUrl=null}$('#detail').showModal();drawDetail();if(selected.type==='poster'){const m=selected.meeting;try{let file;try{file=await posterDB('get',m.id)}catch{}if(!file&&m.poster){file=bundledPosters.get(m.id);if(!file){const r=await fetch(m.poster);if(!r.ok)throw Error('Poster download failed');file=await r.blob();bundledPosters.set(m.id,file)}}if(selected?.key!==key)return;if(file){activePoster=file;posterUrl=URL.createObjectURL(file)}drawDetail()}catch{toast('Could not load this poster. Check your connection and open it again.')}}}
function drawDetail(){const t=selected;if(!t)return;const m=t.meeting,isPoster=t.type==='poster';$('#dialogTag').textContent=isPoster?'POSTER · 3 DAYS BEFORE':'ZOOM INVITATION · 1 DAY BEFORE';$('#detailBody').innerHTML=`<h2 class="detail-title" lang="am">${esc(m.topic)}</h2><div class="detail-meta">Meeting ${prettyDate(m.date)} · ${timeRange(m)} Dubai &nbsp; / &nbsp; Send ${prettyDate(t.due)} &nbsp; ${badge(t)}</div><div class="detail-columns"><div><div class="detail-poster">${posterUrl||m.preview?`<img src="${posterUrl||m.preview}" alt="${activePoster?'Attached original poster':'Canva thumbnail preview'}">`:''}<small>${activePoster?'Poster ready to share':m.preview?'Poster preview':'Attach this month’s poster below'}</small>${m.canva?`<a href="${esc(m.canva)}" target="_blank" rel="noopener noreferrer">Open original in Canva ↗</a>`:''}</div></div><div class="detail-controls"><button class="secondary" id="editFromDetail">Edit this gubae ✎</button><label class="field">Recipient’s WhatsApp number<input id="detailPhone" type="tel" value="${esc(recipient(m))}" placeholder="+971 50 123 4567" autocomplete="off"><span class="field-hint">Include country code. Separate alternate numbers with / . ${extension?.cloud()?(extension.publicAccess()?'Shared with everyone in this workspace.':'Syncs to your private cloud workspace.'):'Saved on this device.'}</span></label><div id="recipientChoice"></div>${isPoster?`<label class="file-label">${activePoster?'Use a different poster (optional)':'Attach original PNG or JPG once'}<input id="attachPoster" type="file" accept="image/png,image/jpeg"><span class="status-note">The original stays in this browser for future sharing. Maximum 12 MB.</span></label><div class="notice">Choose WhatsApp and the intended private chat in the share menu. Your saved number is shown above for reference; file sharing cannot select that contact automatically.</div><div class="detail-actions"><button class="primary" id="sharePoster" ${!activePoster?'disabled':''}>Share poster ↗</button><button class="secondary" id="downloadPoster" ${!activePoster?'disabled':''}>Download original</button></div><div id="shareSupport" class="status-note"></div>`:`<pre class="message-preview">${esc(message(m))}</pre><div class="detail-actions"><button class="primary" id="openWhatsApp">Open in WhatsApp ↗</button></div><div class="status-note">Your invitation opens prefilled in this private chat. Press Send in WhatsApp.</div>`}<div class="sent-action"><span>${sent(t)?'✓ Marked sent '+prettyDate(dubaiDate(new Date(state.sent[t.key]))):'After sending in WhatsApp, confirm it here.'}</span><button class="secondary" id="markSent">${sent(t)?'Undo sent':'Mark as sent ✓'}</button></div></div></div>`;
$('#editFromDetail').onclick=()=>{const id=m.id;$('#detail').close();openEditor(id)};$('#detailPhone').oninput=e=>{state.recipients[m.id]=e.target.value;save();e.target.classList.toggle('invalid',!!e.target.value&&!validPhoneList(e.target.value));stats();renderRecipientChoice(m)};renderRecipientChoice(m);$('#openWhatsApp')?.addEventListener('click',()=>{try{const choices=phoneList(recipient(m));const chosen=choices.length===1?choices[0]:$('#recipientSelect')?.value;if(!chosen)throw Error('Choose which recipient number to open.');const url=waUrl(chosen,message(m));window.open(url,'_blank','noopener,noreferrer');toast('Finish sending in WhatsApp, then mark it sent here.')}catch(e){toast(e.message);$('#detailPhone').focus()}});$('#markSent').onclick=()=>{if(sent(t))delete state.sent[t.key];else state.sent[t.key]=new Date().toISOString();save();render();drawDetail()};$('#attachPoster')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>12*1024*1024){toast('Choose a PNG or JPG under 12 MB.');e.target.value='';return}try{await validateImage(file);await posterDB('put',m.id,file);if(selected?.key!==t.key)return;activePoster=file;if(posterUrl)URL.revokeObjectURL(posterUrl);posterUrl=URL.createObjectURL(file);drawDetail();toast('Original poster attached and saved on this device.')}catch{toast('Could not save this poster. Check storage availability and try a valid image.')}});$('#sharePoster')?.addEventListener('click',async()=>{if(!activePoster)return;const f=new File([activePoster],`gubae-${m.id}-poster.${activePoster.type==='image/png'?'png':'jpg'}`,{type:activePoster.type});if(!navigator.canShare?.({files:[f]})||!navigator.share){toast('This browser cannot share image files. Download the original and attach it in WhatsApp.');return}try{await navigator.share({files:[f]});toast('Share menu closed. Confirm sending in WhatsApp before marking sent.')}catch(e){if(e.name!=='AbortError')toast('Sharing did not finish. Try from your phone or download the original.')}});$('#downloadPoster')?.addEventListener('click',()=>activePoster&&download(activePoster,`gubae-${m.id}-poster.${activePoster.type==='image/png'?'png':'jpg'}`));if(isPoster&&activePoster){const f=new File([activePoster],'poster.png',{type:activePoster.type});$('#shareSupport').textContent=navigator.canShare?.({files:[f]})?'Ready to share. Choose WhatsApp, then the recipient.':'Image sharing is unavailable here. Download the original, or use a supported mobile browser.'}}

function renderRecipientChoice(m){const holder=$('#recipientChoice');if(!holder)return;const choices=phoneList(recipient(m));holder.innerHTML=choices.length>1?`<label class="field">Choose the private chat<select id="recipientSelect"><option value="">Select a number…</option>${choices.map(p=>`<option value="${esc(p)}" ${!phoneDigits(p)?'disabled':''}>${esc(p)}${!phoneDigits(p)?' · check number':''}</option>`).join('')}</select></label>`:recipient(m)&&!validPhoneList(recipient(m))?'<div class="notice bad">Check this number before sending. UAE numbers need 9 digits after +971. The supplied number has been preserved for correction.</div>':'';}

async function validateImage(file){const bitmap=await createImageBitmap(file);if(!bitmap.width||!bitmap.height)throw Error('Invalid image');bitmap.close()}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function exportBackup(){const button=$('#exportBackup');button.disabled=true;button.textContent='Preparing backup…';try{const keys=await posterDB('getAllKeys');const posters={};for(const id of keys){const f=await posterDB('get',id);posters[id]=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})}download(new Blob([JSON.stringify({format:'gubae-v1',exportedAt:new Date().toISOString(),recipients:state.recipients,sent:state.sent,meetingEdits:state.meetingEdits,posters})],{type:'application/json'}),'gubae-backup-'+today+'.json');toast('Backup downloaded, including attached posters.')}catch{toast('Could not export the complete backup. Your saved data remains on this device.')}finally{button.disabled=false;button.textContent='Export backup'}}
async function importBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>200*1024*1024)throw Error('Backup is too large.');const b=JSON.parse(await file.text());if(await extension?.importBackup(b)){e.target.value='';return;}if(b.format!=='gubae-v1'||!b.recipients||!b.sent||typeof b.recipients!=='object'||typeof b.sent!=='object')throw Error('Choose a Gubae backup file.');if(b.meetings){for(const record of b.meetings){const m=baseMeetings.find(m=>m.id===record.id);if(!m||m.topic!==record.topic)throw Error('This contact file belongs to a different meeting list.')}}const ids=new Set(meetings.map(m=>m.id)),taskKeys=new Set(tasks.map(t=>t.key));let prepared=[];for(const[id,data]of Object.entries(b.posters||{})){if(!ids.has(id)||typeof data!=='string'||!/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(data))throw Error('Invalid poster in backup.');const [head,encoded]=data.split(',');const raw=atob(encoded);if(raw.length>12*1024*1024)throw Error('A poster exceeds 12 MB.');const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:head.includes('image/png')?'image/png':'image/jpeg'});await validateImage(blob);prepared.push([id,blob])}const merged={recipients:{...state.recipients},sent:{...state.sent},meetingEdits:{...state.meetingEdits}};for(const[id,edit]of Object.entries(b.meetingEdits||{})){const base=baseMeetings.find(m=>m.id===id);if(!base)throw Error('Unknown gubae in backup.');merged.meetingEdits[id]=normalizeMeetingEdit(base,edit)}for(const[id,v]of Object.entries(b.recipients)){if(ids.has(id)&&typeof v==='string'&&v.length<60)merged.recipients[id]=v}for(const[k,v]of Object.entries(b.sent)){if(taskKeys.has(k)&&typeof v==='string'&&!isNaN(Date.parse(v)))merged.sent[k]=new Date(v).toISOString()}for(const[id,blob]of prepared)await posterDB('put',id,blob);const prior=state;state=merged;if(!save()){state=prior;throw Error('Settings could not be saved.')}rebuildMeetings();view=b.contactsOnly?'recipients':view;render();const bad=meetings.filter(m=>recipient(m)&&!validPhoneList(recipient(m))).length;toast(b.contactsOnly?'Contacts imported. '+(bad?bad+' number needs correction.':'All numbers are ready.'):'Backup restored to this device.')}catch(err){toast(err.message||'Could not restore this backup.')}finally{e.target.value=''}}
function downloadSchedule(){const lines=['Mahber,Meeting date,Dubai time,Poster send date,Link send date,Join link'];for(const m of meetings){const p=tasks.find(t=>t.meeting.id===m.id&&t.type==='poster'),l=tasks.find(t=>t.meeting.id===m.id&&t.type==='link');lines.push([m.topic,m.date,timeRange(m),p.due,l.due,m.link].map(v=>'"'+v.replaceAll('"','""')+'"').join(','))}download(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),'gubae-send-schedule.csv')}
function rebuildMeetings(){meetings=applyMeetingEdits(baseMeetings,state.meetingEdits).filter(m=>dueOnly||programOf(m)===activeProgram);tasks=tasksFor(meetings)}
function openEditor(id){const m=meetings.find(m=>m.id===id);if(!m)return;const base=baseMeetings.find(m=>m.id===id);const values=normalizeMeetingEdit(base,m);$('#editorBody').innerHTML=`<h2 class="section-title">Edit gubae #${id.padStart(2,'0')}</h2><p class="muted">Changes update your announcements and send dates. Check the sync indicator to confirm cloud saving.</p><form id="editForm"><label class="field">Topic<textarea name="topic" required maxlength="300" rows="3" lang="am">${esc(values.topic)}</textarea></label><div class="editor-grid"><label class="field">Meeting date<input name="date" type="date" required value="${values.date}"></label><label class="field">Start time · Dubai<input name="startTime" type="time" required value="${values.startTime}"></label><label class="field">Duration · minutes<input name="durationMinutes" type="number" min="1" max="1440" step="1" required value="${values.durationMinutes}"></label></div><label class="field">Zoom meeting link<input name="link" type="url" ${m.linkPending?'':'required'} value="${esc(values.link)}" placeholder="https://rit.zoom.us/j/12345678901"></label><div class="notice">If you change the date, time, or topic, also update the Zoom meeting and replace the poster. Saving changed details clears this gubae’s sent confirmations so you can resend.</div><p id="editError" class="bad" role="alert"></p><div class="button-row"><button class="primary" type="submit">Save changes</button><button class="secondary" type="button" id="cancelEdit">Cancel</button><button class="secondary" type="button" id="restoreOriginal">Restore original</button></div></form><details class="editor-preview"><summary>Preview updated invitation</summary><pre class="message-preview" id="editPreview"></pre></details>`;const form=$('#editForm');const read=()=>normalizeMeetingEdit(base,Object.fromEntries(new FormData(form)));const preview=()=>{try{const draft={...m,...read()};$('#editPreview').textContent=draft.link?message(draft):'Add a Zoom link to preview this invitation.';$('#editError').textContent=''}catch(e){$('#editError').textContent=e.message}};form.addEventListener('input',preview);form.onsubmit=e=>{e.preventDefault();try{const edit=read();const changed=JSON.stringify(edit)!==JSON.stringify(normalizeMeetingEdit(base,m));if(changed){const next={...state,meetingEdits:{...state.meetingEdits},sent:{...state.sent}};if(JSON.stringify(edit)===JSON.stringify(normalizeMeetingEdit(base,{})))delete next.meetingEdits[id];else next.meetingEdits[id]=edit;delete next.sent[id+':poster'];delete next.sent[id+':link'];const previous=state;state=next;if(!save()){state=previous;$('#editError').textContent='Could not save on this device. Your previous details are unchanged.';return}rebuildMeetings()}$('#editor').close();render();toast(changed?'Gubae updated. Announcement dates and invitation refreshed.':'No changes to save.')}catch(err){$('#editError').textContent=err.message}};$('#cancelEdit').onclick=()=>$('#editor').close();$('#restoreOriginal').onclick=()=>{const original=normalizeMeetingEdit(base,{});for(const[k,v]of Object.entries(original))form.elements.namedItem(k).value=v;preview();toast('Original details loaded. Select Save changes to apply them.')};preview();$('#editor').showModal()}
$('#closeEditor').onclick=()=>$('#editor').close();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;query='';render()});$('#howButton').onclick=()=>$('#help').showModal();$('#closeHelp').onclick=()=>$('#help').close();$('#closeDialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{selected=null;activePoster=null;if(posterUrl){URL.revokeObjectURL(posterUrl);posterUrl=null}render()});for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
function refreshDay(){const d=dubaiDate();if(d!==today||((dueOnly||view==='meetings')&&!document.activeElement?.matches('input,textarea,select')&&!document.querySelector('dialog[open]'))){today=d;render();if(selected)drawDetail()}}setInterval(refreshDay,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDay()});
try{const r=await fetch('./meetings.json');if(!r.ok)throw Error('Meeting schedule could not load.');bundledMeetings=await r.json();baseMeetings=[...bundledMeetings];if(!baseMeetings.length)throw Error('The meeting schedule is empty.');rebuildMeetings();render()}catch(e){$('#content').innerHTML=`<div class="empty"><strong>Schedule unavailable</strong><p>${esc(e.message)}</p><button class="primary" id="retry">Try again</button></div>`;$('#retry').onclick=()=>location.reload()}

extension=createWorkspace({state:()=>state,base:()=>baseMeetings,bundled:()=>bundledMeetings,program:()=>activeProgram,selectProgram:id=>{activeProgram=id;localStorage.setItem('gubae-active-program',id);rebuildMeetings();render()},setBase:rows=>{baseMeetings=rows;rebuildMeetings()},restoreLocal:()=>{try{state=JSON.parse(localStorage.getItem(KEY)||'null')||{recipients:{},sent:{},meetingEdits:{}}}catch{state={recipients:{},sent:{},meetingEdits:{}}}},meetings:()=>[...meetings],view:()=>view,setState:next=>{state=next;rebuildMeetings()},save,render,navigate:v=>{view=v;query='';render()},toast,download});await extension.start();
